<h1 class="h3 mb-3">Stammdaten</h1><ul class="nav nav-tabs" role="tablist"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#vehicles">Fahrzeugtypen</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#expansions">Erweiterungen</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#trainings">Ausbildungen</button></li></ul><div class="tab-content bg-white border border-top-0 p-3"><div class="tab-pane fade show active" id="vehicles"><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Name</th><th>Kategorie</th><th>Wache</th><th>Erweiterung</th><th>Personal</th><th>Ausbildung</th><th>Kosten</th></tr></thead><tbody><?php foreach($vehicleTypes as $v): ?><tr><td><?=e($v['name'])?></td><td><?=e($v['category'])?></td><td><?=e($v['station_type'])?></td><td><?=e($v['required_expansion'])?></td><td><?=e($v['personnel_required'])?></td><td><?=e($v['required_training'])?></td><td><?=money_fmt($v['credits'])?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="tab-pane fade" id="expansions"><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Erweiterung</th><th>Wachtyp</th><th>Kosten</th><th>Bauzeit</th><th>Freischaltung</th></tr></thead><tbody><?php foreach($expansions as $e2): ?><tr><td><?=e($e2['name'])?></td><td><?=e($e2['station_type'])?></td><td><?=money_fmt($e2['cost'])?></td><td><?=e($e2['build_time'])?></td><td><?=e($e2['unlocks'])?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="tab-pane fade" id="trainings"><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Ausbildung</th><th>Organisation</th><th>Schule</th><th>Dauer</th></tr></thead><tbody><?php foreach($trainings as $t): ?><tr><td><?=e($t['name'])?></td><td><?=e($t['organisation'])?></td><td><?=e($t['school'])?></td><td><?=e($t['duration_days'])?> Tage</td></tr><?php endforeach; ?></tbody></table></div></div></div>